<template>
  <div class="docnet-project-detail">
    <!-- Loading -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <!-- Not found -->
    <div v-else-if="!project" class="text-center q-pa-xl">
      <q-icon name="search_off" size="64px" color="grey-5" />
      <p class="q-mt-md text-grey-6">Project not found</p>
      <f-btn appearance="flat" label="Back to Projects" icon="arrow_back" @click="router.push('/doc-net/projects')" />
    </div>

    <!-- Project detail -->
    <div v-else>
      <!-- Header -->
      <div class="project-header row items-center q-mb-md">
        <f-btn appearance="flat" icon="arrow_back" dense class="q-mr-sm" @click="router.push('/doc-net/projects')" />
        <h2 class="project-header__title">{{ project.name }}</h2>
        <StatusBadge :status="project.status" size="md" class="q-ml-sm" />
        <q-space />
        <q-btn-dropdown
          flat
          dense
          round
          icon="more_vert"
          dropdown-icon="none"
          class="actions-menu-btn"
        >
          <q-list dense class="actions-menu-list">
            <q-item clickable v-close-popup dense @click="startEditProject">
              <q-item-section>
                <div class="row items-center no-wrap q-gutter-x-sm">
                  <q-icon name="edit" size="16px" />
                  <span>Edit project</span>
                </div>
              </q-item-section>
            </q-item>
            <q-item clickable v-close-popup dense @click="showDeleteConfirm = true" class="text-negative">
              <q-item-section>
                <div class="row items-center no-wrap q-gutter-x-sm">
                  <q-icon name="delete" size="16px" />
                  <span>Delete project</span>
                </div>
              </q-item-section>
            </q-item>
          </q-list>
        </q-btn-dropdown>
      </div>

      <!-- Description + Properties -->
      <q-card flat bordered class="detail-card q-mb-md">
        <q-card-section>
          <div class="detail-section-label">Description</div>
          <div class="detail-description markdown-body" v-html="renderMarkdown(project.description || '---')" />

          <!-- Properties list -->
          <q-separator class="q-my-md" />
          <div class="properties-list">
            <div v-if="project.owner_name" class="properties-list__item">
              <span class="properties-list__label"><q-icon name="person" size="14px" class="q-mr-xs" />Owner</span>
              <span>{{ project.owner_name }}</span>
            </div>
            <div v-if="project.due_date" class="properties-list__item">
              <span class="properties-list__label"><q-icon name="event" size="14px" class="q-mr-xs" />Due date</span>
              <span class="text-caption">{{ formatDate(project.due_date) }}</span>
            </div>
            <div class="properties-list__item">
              <span class="properties-list__label"><q-icon name="schedule" size="14px" class="q-mr-xs" />Created</span>
              <span class="text-caption">{{ formatDate(project.created_on) }}</span>
            </div>
            <div v-if="project.last_modified_on" class="properties-list__item">
              <span class="properties-list__label"><q-icon name="update" size="14px" class="q-mr-xs" />Updated</span>
              <span class="text-caption">{{ formatDate(project.last_modified_on) }}</span>
            </div>
          </div>
        </q-card-section>
      </q-card>

      <!-- Missions -->
      <q-card flat bordered class="detail-card q-mb-md">
        <q-card-section>
          <div class="detail-section-label">
            Missions
            <q-badge
              v-if="allMissions.length > 0"
              color="grey-5"
              text-color="dark"
              class="q-ml-sm"
            >
              {{ allMissions.length }}
            </q-badge>
            <q-space />
            <q-btn flat dense size="sm" icon="add" label="Link Mission" no-caps @click="showLinkMissionDialog = true" />
          </div>

          <div v-if="allMissions.length === 0" class="text-grey-6 text-caption q-pa-sm">
            No missions linked to this project yet
          </div>

          <div v-else class="project-missions">
            <div
              v-for="mission in allMissions"
              :key="mission.id"
              class="mission-row"
              @click="router.push('/doc-net/missions/' + mission.id)"
            >
              <span class="mission-row__name">{{ mission.name }}</span>
              <q-space />
              <StatusBadge :status="mission.status" size="sm" />
            </div>
          </div>
        </q-card-section>
      </q-card>

      <!-- Link Mission Dialog -->
      <q-dialog v-model="showLinkMissionDialog">
        <q-card class="project-form-card">
          <q-card-section class="project-form-header">
            <div class="text-h6">Link Missions</div>
            <q-space />
            <q-btn icon="close" flat round dense @click="showLinkMissionDialog = false" />
          </q-card-section>

          <q-separator />

          <q-card-section class="project-form-body">
            <q-select
              v-model="selectedMissionIds"
              :options="unlinkableMissionOptions"
              multiple
              outlined
              dense
              emit-value
              map-options
              use-input
              input-debounce="200"
              label="Select missions"
              options-dense
            />
          </q-card-section>

          <q-separator />

          <q-card-actions align="right" class="q-pa-md">
            <f-btn appearance="flat" label="Cancel" @click="showLinkMissionDialog = false" />
            <f-btn
              appearance="primary"
              label="Link"
              :loading="linkingMissions"
              :disable="selectedMissionIds.length === 0"
              @click="onLinkMissions"
            />
          </q-card-actions>
        </q-card>
      </q-dialog>

      <!-- Edit Project Dialog -->
      <q-dialog v-model="showEditDialog">
