          <q-card-section class="project-form-header">
            <div class="text-h6">Edit Project</div>
            <q-space />
            <q-btn icon="close" flat round dense @click="showEditDialog = false" />
          </q-card-section>

          <q-separator />

          <q-card-section class="project-form-body q-gutter-sm">
            <q-input
              v-model="editValues.name"
              label="Name *"
              outlined
              dense
              autofocus
              :rules="[val => !!val || 'Name is required']"
            />
            <q-input
              v-model="editValues.description"
              label="Description"
              outlined
              dense
              type="textarea"
              :input-style="{ minHeight: '60px' }"
              autogrow
            />
            <div class="row q-gutter-sm">
              <q-select
                v-model="editValues.status"
                :options="statusOptions"
                label="Status"
                outlined
                dense
                emit-value
                map-options
                class="col"
              />
