              v-model="editValues.due_date"
              label="Due Date"
              outlined
              dense
              type="date"
            />
          </q-card-section>

          <q-separator />

          <q-card-actions align="right" class="q-pa-md">
            <f-btn appearance="flat" label="Cancel" @click="showEditDialog = false" />
            <f-btn
              appearance="primary"
              label="Save"
              :disable="!editValues.name?.trim()"
              @click="saveEditProject"
            />
          </q-card-actions>
        </q-card>
      </q-dialog>

      <!-- Delete Confirmation Dialog -->
      <q-dialog v-model="showDeleteConfirm">
