<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { useRouter } from 'vue-router';
import { useDocNetProjectStore } from 'src/store/DocNet/docnet-projects.store';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import StatusBadge from '../shared/StatusBadge.vue';
import { renderMarkdown } from 'src/utils/markdown';

import type { DocNetMissionSummary } from 'src/@types/docnet';

export default defineComponent({
  name: 'DocNetProjectDetail',
  components: { StatusBadge },

  setup() {
    const router = useRouter();
    const projectStore = useDocNetProjectStore();
    const missionStore = useDocNetMissionStore();
    return { router, projectStore, missionStore };
  },

  data() {
    return {
      loading: false,
      showDeleteConfirm: false,
      showLinkMissionDialog: false,
      showEditDialog: false,
      deleting: false,
      linkingMissions: false,
      selectedMissionIds: [] as string[],
      editValues: {} as Record<string, any>,
    };
  },

  computed: {
    project() {
      return this.projectStore.currentProject;
    },
    allMissions(): DocNetMissionSummary[] {
      if (!this.project) return [];
      const direct = this.project.missions || [];
      const extra = this.project.all_missions || [];
      const seen = new Set(direct.map((m: DocNetMissionSummary) => m.id));
      return [...direct, ...extra.filter((m: DocNetMissionSummary) => !seen.has(m.id))];
    },
    linkedMissionIds(): Set<string> {
      return new Set(this.allMissions.map((m: DocNetMissionSummary) => m.id));
    },
    unlinkableMissionOptions(): { label: string; value: string }[] {
      return this.missionStore.missions
        .filter((m) => !this.linkedMissionIds.has(m.id))
        .map((m) => ({ label: m.name, value: m.id }));
    },
    statusOptions() {
      return [
        { label: 'Active', value: 'active' },
        { label: 'Completed', value: 'completed' },
      ];
    },
  },

  methods: {
    renderMarkdown,

    formatDate(isoString: string): string {
      if (!isoString) return '';
      const date = new Date(isoString);
      if (isNaN(date.getTime())) return '';
      return date.toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      });
    },

    startEditProject(): void {
      if (!this.project) return;
      this.editValues = {
        name: this.project.name,
        description: this.project.description || '',
        status: this.project.status,
        owner_name: this.project.owner_name || '',
        due_date: this.project.due_date
          ? new Date(this.project.due_date).toISOString().split('T')[0]
          : '',
      };
      this.showEditDialog = true;
    },

    async saveEditProject(): Promise<void> {
      if (!this.project || !this.editValues.name?.trim()) return;
      try {
        const payload: Record<string, any> = {
          name: this.editValues.name.trim(),
          description: this.editValues.description.trim(),
          status: this.editValues.status,
          owner_name: this.editValues.owner_name.trim() || null,
        };
        if (this.editValues.due_date) {
          payload.due_date = this.editValues.due_date;
        }
        await this.projectStore.updateProject(this.project.id, payload);
        this.showEditDialog = false;
      } catch (error) {
        console.error('Failed to update project:', error);
        notify.error('Failed to update project');
      }
    },

    async onLinkMissions() {
      if (!this.project || this.selectedMissionIds.length === 0) return;
      this.linkingMissions = true;
      try {
        const projectId = this.project.id;
        for (const missionId of this.selectedMissionIds) {
          const mission = this.missionStore.missions.find((m) => m.id === missionId);
          const existingIds = mission?.project_ids || (mission?.project_id ? [mission.project_id] : []);
          const newIds = [...new Set([...existingIds, projectId])];
          await this.missionStore.updateMission(missionId, {
            project_id: newIds[0] || null,
            project_ids: newIds,
          });
        }
        this.showLinkMissionDialog = false;
        this.selectedMissionIds = [];
        await this.projectStore.fetchProject(projectId);
      } catch (error) {
        console.error('Failed to link missions:', error);
        notify.error('Failed to link missions');
      } finally {
        this.linkingMissions = false;
      }
    },

    async onDelete() {
      if (!this.project) return;
      this.deleting = true;
      try {
        await this.projectStore.deleteProject(this.project.id);
        notify.success('Project deleted');
        this.router.push('/doc-net/projects');
      } catch (error) {
        console.error('Failed to delete project:', error);
        notify.error('Failed to delete project');
      } finally {
        this.deleting = false;
      }
    },
  },

  async mounted() {
    const id = this.$route.params.id as string;
    this.loading = true;
    try {
      await Promise.all([
        this.projectStore.fetchProject(id),
        this.missionStore.fetchMissions(),
      ]);
    } finally {
      this.loading = false;
    }
  },
});
</script>

